const body = $input.first().json.body;
const from = body.From || '';
const messageBody = (body.Body || '').toLowerCase().trim();

let intent = 'default';
let sessionData = {};

// Detect intent
if (/^(hola|buenas|buenos|hey|hi|hello|buen dia|buenas tardes|buenas noches|saludos|qué tal|que tal|ola)/.test(messageBody)) {
  intent = 'greeting';
} else if (/(servicio|precio|costo|cuanto|cuánto|vale|cuesta|tarifa|lista)/.test(messageBody)) {
  intent = 'servicios';
} else if (/(agendar|cita|reservar|reserva|turno|appointment|quiero un|necesito un|pedir)/.test(messageBody)) {
  intent = 'agendar';
} else if (/(horario|hora|cuando|cuándo|atienden|abren|cierran|disponible|abierto)/.test(messageBody)) {
  intent = 'horarios';
} else if (/(ubicacion|ubicación|donde|dónde|dirección|direccion|como llegar|maps|lugar|local)/.test(messageBody)) {
  intent = 'ubicacion';
} else if (/(confirm|sí|si|confirmo|acepto|de acuerdo|ok|dale|listo|claro|perfecto)/.test(messageBody)) {
  intent = 'confirmacion';
} else if (/(cancelar|cancel|no quiero|no puedo|no voy)/.test(messageBody)) {
  intent = 'cancelar';
}

// Build reply message based on intent
let replyMessage = '';

switch (intent) {
  case 'greeting':
    replyMessage = `✂️ *¡Bienvenido a Barbería Élite!* ✂️

Hola, soy tu asistente virtual. ¿En qué puedo ayudarte hoy?

📋 *MENÚ PRINCIPAL:*
1️⃣ Ver *servicios y precios*
2️⃣ *Agendar* una cita
3️⃣ Ver nuestros *horarios*
4️⃣ Consultar *ubicación*

Escribe la opción que deseas o simplemente cuéntame qué necesitas. 😊`;
    break;

  case 'servicios':
    replyMessage = `💈 *SERVICIOS Y PRECIOS - Barbería Élite* 💈

✂️ *Corte de cabello* — $25.000
🧔 *Arreglo de barba* — $15.000
🔥 *Combo (Corte + Barba)* — $35.000
🎨 *Tinte / Color* — $45.000

_Todos nuestros servicios incluyen lavado y estilizado final._

¿Deseas *agendar una cita*? Solo escribe "agendar" 📅`;
    break;

  case 'agendar':
    replyMessage = `📅 *AGENDAR TU CITA* 📅

¡Perfecto! Vamos a reservar tu turno en Barbería Élite.

Por favor envíame la siguiente información en un solo mensaje con este formato:

👤 *Nombre:* [Tu nombre completo]
📅 *Fecha:* [DD/MM/YYYY]
🕐 *Hora:* [HH:MM AM/PM]
✂️ *Servicio:* [Corte / Barba / Combo / Tinte]

_Ejemplo:_
Nombre: Juan Pérez
Fecha: 15/06/2026
Hora: 10:00 AM
Servicio: Combo

⏰ Horarios disponibles: Lunes a Sábado, 9:00 AM - 7:00 PM`;
    break;

  case 'horarios':
    replyMessage = `🕐 *HORARIOS DE ATENCIÓN* 🕐

📅 *Lunes a Viernes:* 9:00 AM — 7:00 PM
📅 *Sábados:* 9:00 AM — 6:00 PM
🚫 *Domingos:* Cerrado

_Atendemos con y sin cita previa, aunque recomendamos reservar para evitar esperas._

¿Quieres *agendar tu cita* ahora? Escribe "agendar" 📲`;
    break;

  case 'ubicacion':
    replyMessage = `📍 *NUESTRA UBICACIÓN* 📍

🏪 *Barbería Élite*
📫 Calle 10 #43-15, El Poblado
🌆 Medellín, Antioquia

🗺️ *Cómo llegar:*
Estamos a 2 cuadras del Parque El Poblado, cerca al metro Aguacatala.

📞 *WhatsApp:* Este mismo número
🅿️ *Parqueadero:* Disponible en la calle

¿Necesitas algo más? Puedo ayudarte a *agendar una cita* 📅`;
    break;

  case 'confirmacion':
    // Extract appointment data from message if present
    const nombreMatch = messageBody.match(/nombre[:\s]+([^\n]+)/i);
    const fechaMatch = messageBody.match(/fecha[:\s]+([^\n]+)/i);
    const horaMatch = messageBody.match(/hora[:\s]+([^\n]+)/i);
    const servicioMatch = messageBody.match(/servicio[:\s]+([^\n]+)/i);

    sessionData.nombre = nombreMatch ? nombreMatch[1].trim() : 'Cliente';
    sessionData.fecha = fechaMatch ? fechaMatch[1].trim() : '';
    sessionData.hora = horaMatch ? horaMatch[1].trim() : '';
    sessionData.servicio = servicioMatch ? servicioMatch[1].trim() : 'Servicio';
    sessionData.from = from;

    replyMessage = `✅ *¡CITA CONFIRMADA!* ✅

🎉 ¡Listo, ${sessionData.nombre}! Tu cita ha sido registrada exitosamente.

📋 *Resumen de tu cita:*
👤 Nombre: ${sessionData.nombre}
📅 Fecha: ${sessionData.fecha}
🕐 Hora: ${sessionData.hora}
✂️ Servicio: ${sessionData.servicio}

📍 *Barbería Élite*
Calle 10 #43-15, El Poblado, Medellín

⚠️ *Recuerda:*
• Llega 5 minutos antes
• Si necesitas cancelar, avísanos con 2 horas de anticipación

¡Te esperamos! 💈✨`;
    break;

  case 'cancelar':
    replyMessage = `😢 *Cita Cancelada*

Entendemos que los planes cambian. Tu cita ha sido cancelada.

Cuando quieras reagendar, solo escribe *"agendar"* y con gusto te ayudamos.

¡Hasta pronto! ✂️💈`;
    break;

  default:
    replyMessage = `🤖 Hola, soy el asistente de *Barbería Élite*.

No entendí bien tu mensaje, pero puedo ayudarte con:

✂️ *Servicios y precios* — escribe "servicios"
📅 *Agendar una cita* — escribe "agendar"
🕐 *Horarios* — escribe "horarios"
📍 *Ubicación* — escribe "ubicación"

¿En qué te puedo ayudar? 😊`;
}

return [{
  json: {
    intent,
    replyMessage,
    from,
    originalMessage: body.Body || '',
    sessionData,
    twilioAccountSid: body.AccountSid || '',
    toNumber: body.To || ''
  }
}];

const sessionData = $input.first().json.sessionData;

// Parse date from DD/MM/YYYY format
function parseDate(dateStr) {
  if (!dateStr) return null;
  const parts = dateStr.split('/');
  if (parts.length === 3) {
    return `${parts[2]}-${parts[1].padStart(2,'0')}-${parts[0].padStart(2,'0')}`;
  }
  return dateStr;
}

// Parse time from HH:MM AM/PM format
function parseTime(timeStr) {
  if (!timeStr) return '10:00:00';
  const normalized = timeStr.toUpperCase().trim();
  const match = normalized.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/);
  if (!match) return '10:00:00';
  let hours = parseInt(match[1]);
  const minutes = match[2];
  const period = match[3];
  if (period === 'PM' && hours !== 12) hours += 12;
  if (period === 'AM' && hours === 12) hours = 0;
  return `${String(hours).padStart(2,'0')}:${minutes}:00`;
}

const parsedDate = parseDate(sessionData.fecha);
const parsedTime = parseTime(sessionData.hora);

const startDateTime = `${parsedDate}T${parsedTime}-05:00`; // Colombia timezone UTC-5

// Add 1 hour for end time
const startDate = new Date(`${parsedDate}T${parsedTime}`);
startDate.setHours(startDate.getHours() + 1);
const endTime = `${String(startDate.getHours()).padStart(2,'0')}:${String(startDate.getMinutes()).padStart(2,'0')}:00`;
const endDateTime = `${parsedDate}T${endTime}-05:00`;

return [{
  json: {
    calendarEvent: {
      summary: `💈 ${sessionData.servicio} - ${sessionData.nombre}`,
      description: `Cita en Barbería Élite\n\nCliente: ${sessionData.nombre}\nServicio: ${sessionData.servicio}\nWhatsApp: ${sessionData.from}`,
      location: 'Calle 10 #43-15, El Poblado, Medellín, Antioquia',
      start: {
        dateTime: startDateTime,
        timeZone: 'America/Bogota'
      },
      end: {
        dateTime: endDateTime,
        timeZone: 'America/Bogota'
      },
      reminders: {
        useDefault: false,
        overrides: [
          { method: 'popup', minutes: 60 },
          { method: 'popup', minutes: 15 }
        ]
      },
      colorId: '9'
    },
    sessionData
  }
}];
